import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.DTwTvi8b.js";const u=JSON.parse('{"title":"0012 评审小组：首轮并行评审，评审者核实汇总","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0012-review-panel.md","filePath":"reference/adr/0012-review-panel.md","lastUpdated":null}'),o={name:"reference/adr/0012-review-panel.md"};function d(l,e,n,c,s,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<div><h1 id="_0012-评审小组-首轮并行评审-评审者核实汇总" tabindex="-1">0012 评审小组：首轮并行评审，评审者核实汇总 <a class="header-anchor" href="#_0012-评审小组-首轮并行评审-评审者核实汇总" aria-label="Permalink to &quot;0012 评审小组：首轮并行评审，评审者核实汇总&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>单一模型评审容易有固定的盲区；参考 pstack 的 <code>/interrogate</code>，多个模型独立评审能发现更多问题。但成员意见直接投票会放大误报，而且并行的成员在同一个目录里提交代码会互相冲突。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>配置 <code>reviewPanel</code> 开启，默认关闭；默认只用于标准档、方案审核和代码评审的第一轮。后续轮次只核对修复，用单个评审者。</li><li>成员并行运行，只读代码，各写一份意见文件到 <code>&lt;功能目录&gt;/review-panel/</code>，不提交、不写 <code>progress.md</code> 和 <code>decisions.tsv</code>。</li><li>配置的 <code>reviewer</code> 作为汇总者，逐条核实并归入&quot;必须修改 / 建议修改 / 留给人决定 / 已驳回&quot;四类；结论只依据核实后的&quot;必须修改&quot;，不按成员数量投票。被驳回和留给人决定的意见记入 <code>decisions.tsv</code>，最终报告展示。</li><li>部分成员失败时只汇总完成的成员；全部失败时该步骤失败。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>开启后每次评审多出 N 个 agent 的用量。汇总者的核实质量决定了效果，需要通过评估观察误报和漏报。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0012-review-panel.md">docs/adr/0012-review-panel.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0012-review-panel.md">在 GitHub 上编辑</a></p>',2)])])}const _=a(o,[["render",d]]);export{u as __pageData,_ as default};
